    bore_face_ids = [44, 46, 49, 50, 51, 52]
    faces = shape.Faces()
    target_edges = []

    for face_id in bore_face_ids:
        if face_id >= len(faces):
            raise IndexError(
                f"Expected bore FACE {face_id}, but model has only {len(faces)} faces"
            )

        face = faces[face_id]
        if face.geomType() != "CYLINDER":
            raise ValueError(
                f"FACE {face_id} is not cylindrical: {face.geomType()}"
            )

