        ]
        if len(circular_edges) != 2:
            raise ValueError(
                f"Expected two circular boundary edges on bore FACE {face_id}, "
                f"found {len(circular_edges)}"
            )

        for edge in circular_edges:
            if not any(
                edge.wrapped.IsSame(existing.wrapped)
                for existing in target_edges
            ):
                target_edges.append(edge)

    if len(target_edges) != 12:
        raise ValueError(
            f"Expected 12 unique hole-end edges, found {len(target_edges)}"
        )

