    if not edited_shape.isValid():
        raise ValueError("Chamfer operation produced an invalid shape")
    if len(edited_shape.Solids()) != 1:
        raise ValueError(
            "Chamfer operation should preserve one solid, "
            f"found {len(edited_shape.Solids())}"
        )

